syntax:
C++ syntax for inheritance and virtual destructors with implementation notes:

class Base {
public:
    virtual ~Base() {}  // Virtual destructor ensures proper polymorphic deletion
    // The vtable for Base is set up here, with the 'this' pointer pointing to the Base subobject.
};

class Derived : public Base {
public:
    ~Derived() override {}  // Override ensures the correct vtable entry is used
    // In memory, Derived object layout: [vtable pointer] [Base members] [Derived members]
    // When calling a virtual function via Base*, 'this' may be adjusted by the offset of Base within Derived.
};

// Deletion syntax:
Derived* d = new Derived();
Base* b = d;  // b points to the Base subobject inside Derived
// Implementation note: delete b; adjusts 'this' to the start of Derived before destruction.
